"""가상 연금 데모. 실제 금융 정책, 고객 데이터, 계좌 변경 기능이 아니다."""


class PensionRuleError(ValueError):
    def __init__(self, code, message, status=409):
        super().__init__(message)
        self.code = code
        self.status = status


def validate_registration(retirement_registered):
    """REQ-101: 데모 등록 확인값이 불리언 True여야 가입할 수 있다."""
    if retirement_registered is not True:
        raise PensionRuleError(
            "RETIREMENT_NOT_REGISTERED",
            "데모 퇴직 등록을 먼저 완료해야 가입할 수 있습니다.",
        )


def enroll_pension(retirement_registered):
    """등록 확인 후 가상의 가입 결과를 반환한다."""
    validate_registration(retirement_registered)
    return {"enrollment_status": "ENROLLED"}


def validate_fund_change(account_status):
    """REQ-102: 데모 계좌 상태가 정확히 ACTIVE여야 변경할 수 있다."""
    if account_status != "ACTIVE":
        raise PensionRuleError(
            "ACCOUNT_NOT_ACTIVE",
            "데모 ACTIVE 계좌에서만 펀드를 변경할 수 있습니다.",
        )


def change_fund(account_status, target_fund_code):
    """계좌 상태를 먼저 확인하고 가상의 펀드 변경 결과를 반환한다."""
    validate_fund_change(account_status)
    if target_fund_code not in ("DEMO-FUND-A", "DEMO-FUND-B"):
        raise PensionRuleError(
            "INVALID_TARGET_FUND",
            "데모 펀드 코드는 DEMO-FUND-A 또는 DEMO-FUND-B여야 합니다.",
            status=400,
        )
    return {"fund_change_status": "CHANGED", "fund_code": target_fund_code}


def handle_post(path, payload):
    """service:pension-api 계약 어댑터. payload는 JSON 객체에 해당하는 dict."""
    try:
        # POST /api/pension/enrollments service:pension-api
        if path == "/api/pension/enrollments":
            return 201, enroll_pension(payload.get("retirement_registered"))
        # POST /api/pension/fund-changes service:pension-api
        if path == "/api/pension/fund-changes":
            return 200, change_fund(
                payload.get("account_status"), payload.get("target_fund_code")
            )
    except PensionRuleError as error:
        return error.status, {"error": error.code, "message": str(error)}
    return 404, {"error": "ROUTE_NOT_FOUND", "message": "데모 경로가 없습니다."}
